class TelemetryWidget {
  constructor(endpoint) {
    this.endpoint = endpoint;
    this.timerId = null;
  }

  start() {
    // BUG: no guard against multiple start() calls
    this.timerId = setInterval(() => {
      console.log("Heartbeat:", this.endpoint);
    }, 1000);
  }

  // Missing dispose() cleanup
}
